function useRenderCount() {
  const ref = useRef(0);
  ref.current += 1;
  return ref.current;
}

function Plain() {
  const n = useRenderCount();
  return <p>Plain child renders: {n}</p>;
}
const Memoized = memo(function Memoized() {
  const n = useRenderCount();
  return <p>Memoized child renders: {n}</p>;
});

function App() {
  const [count, setCount] = useState(0);
  const n = useRenderCount();
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setCount(count + 1)}>Parent state: {count}</button>
      <p>Parent renders: {n}</p>
      <Plain />
      <Memoized />
    </div>
  );
}

let slowRenders = 0;
function SlowTree() {
  slowRenders += 1;
  console.log("SlowTree rendered", slowRenders);
  return <p>I am an expensive tree (renders: {slowRenders})</p>;
}

// BAD: state in the parent re-renders SlowTree on every keystroke
function Bad() {
  const [text, setText] = useState("");
  return (
    <div>
      <input value={text} onChange={(e) => setText(e.target.value)} placeholder="bad: parent state" />
      <SlowTree />
    </div>
  );
}

