const ITEM_H = 28;
const COUNT = 10000;
const VIEW_H = 168;

function VirtualList() {
  const [scrollTop, setScrollTop] = useState(0);
  const overscan = 3;
  const start = Math.max(0, Math.floor(scrollTop / ITEM_H) - overscan);
  const visible = Math.ceil(VIEW_H / ITEM_H) + overscan * 2;
  const end = Math.min(COUNT, start + visible);

  const rows = [];
  for (let i = start; i < end; i++) {
    rows.push(
      <div key={i} style={{ position: "absolute", top: i * ITEM_H, height: ITEM_H, left: 0, right: 0, lineHeight: ITEM_H + "px", paddingLeft: 8, borderBottom: "1px solid #eee" }}>
        Row {i + 1}
      </div>
    );
  }
  return (
    <div style={{ height: VIEW_H, overflow: "auto", border: "1px solid #ccc" }} onScroll={(e) => setScrollTop(e.currentTarget.scrollTop)}>
      <div style={{ height: COUNT * ITEM_H, position: "relative" }}>{rows}</div>
    </div>
  );
}

function App() {
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <p>10,000 rows, only ~{Math.ceil(VIEW_H / ITEM_H) + 6} are in the DOM.</p>
      <VirtualList />
    </div>
  );
}

