const Profiler = React.Profiler;

function Heavy({ n }) {
  let total = 0;
  for (let i = 0; i < 200000; i++) total += i % (n + 1);
  return <p>Result: {total}</p>;
}

function App() {
  const [n, setN] = useState(1);
  const lastRef = useRef(null);       // do NOT setState inside onRender: it would loop
  const [shown, setShown] = useState(null);

  function onRender(id, phase, actualDuration) {
    lastRef.current = { id, phase, ms: actualDuration.toFixed(2) };
    console.log("Profiler:", id, phase, actualDuration.toFixed(2) + "ms");
  }

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setN(n + 1)}>Re-render heavy ({n})</button>{" "}
      <button onClick={() => setShown(lastRef.current)}>Show last measurement</button>
      <Profiler id="Heavy" onRender={onRender}>
        <Heavy n={n} />
      </Profiler>
      {shown && <p>{shown.id} {shown.phase}: {shown.ms} ms</p>}
    </div>
  );
}

